  function rafflePrizeRows(rows,readOnly,offset){return rows.map(function(r,i){var noSeat=readOnly||r.seatStatus==='not_seated',editable=!readOnly&&r.editable!==false,status=readOnly?'Не сел · возврат '+money(r.amount):r.seatStatus==='not_seated'?'Не сел':r.seatStatus===''?'Посадка не отмечена':'Сел',prize=readOnly?money(r.issueAmount):r.prize||'Приз';return '<article data-prize-search-text="'+esc([r.name,r.playerId,r.title,r.prize].filter(Boolean).join(' '))+'" class="deposits__prize-row deposits__prize-row--compact '+(noSeat?'deposits__prize-row--not-seated':'deposits__prize-row--seated')+'"><div class="deposits__prize-line"><strong title="'+esc(r.name||r.playerId)+'">'+(i+1+(offset||0))+'. '+esc(r.name||r.playerId)+'</strong>'+(editable?'<button type="button" class="deposits__secondary" data-dep="raffle-prize-edit" data-prize-key="'+esc(r.key)+'" aria-label="'+(r.outcome?'Изменить':'Указать')+' выигрыш '+esc(r.name)+'">'+(r.outcome?money(r.amount):'Указать')+'</button>':'')+'</div><small title="'+esc(r.title+' · '+prize)+'">'+(r.playerId?'ID '+esc(r.playerId)+' · ':'')+esc(prize)+' · '+esc(status)+(readOnly?'':r.outcome?' · Возврат '+money(r.amount):'')+'</small></article>';}).join('')||'<p class="deposits__hint">За выбранный период записей нет.</p>';}

