  function reportCopyText(stats){
    var period=stats.period||{},rows=stats.destinations||[];
    function amount(id){var row=rows.find(function(d){return d.id===id;});return row&&row.amount||0;}
    var separate=['withdrawals','payment-links','runex','exchip','r-crypto','other','transfer','manager-tips'];
    var providers=rows.filter(function(d){return separate.indexOf(d.id)<0&&d.amount!==null;});
    var lines=['Отчёт',period.from?period.from+' — '+period.to+' · 06:00–06:00 · Москва · включая архив':'За всё время · включая архив','','Вся детализация отчёта:','Депозит: '+money(stats.deposits),'На выводы: '+money(amount('withdrawals')),'В платёжки: '+money(providers.reduce(function(sum,d){return sum+d.amount;},0))];
    providers.forEach(function(d){lines.push('  - '+d.title+': '+money(d.amount));});
    if(stats.tipsCashedOut)lines.push('Обналичены чаевые (депозиты): '+money(stats.tipsCashedOut));
    lines.push('Рунекс: '+money(amount('runex')),'Эксчип бот: '+money(amount('exchip')),'Роман Крипта: '+money(amount('r-crypto')),'Другое: '+money(amount('other')));
    (stats.otherCategories||[]).forEach(function(d){lines.push('  - '+d.title.replace(/\s+/g,' ')+': '+money(d.amount));});
    lines.push('Перевод: '+money(amount('transfer')),'','Выводы Эксчип: '+money(stats.exchipWithdrawals),...(stats.allfriendsPaid?['Вывели в Олфрендс: '+money(stats.allfriendsPaid)]:[]),...(stats.ownerPaid?['Выплачено владельцем: '+money(stats.ownerPaid)]:[]),'Вывод снятия с кассы: '+money(stats.cashWithdrawals),'Чаевые: '+money(stats.tips),'Всего снято с чаевыми: '+money((stats.cashWithdrawals||0)+(stats.tips||0)),'Возвраты в кассу: '+money(stats.returned),'Бонусы: '+money(stats.bonuses),'Заморожено: '+money((stats.managers||[]).reduce(function(sum,m){return sum+(m.reserved||0);},0)));
    if(stats.spinReturnsAvailable===false)lines.push('Возвраты круток не загружены — итог возвратов неполный.');
    if(stats.raffleReturnsAvailable===false)lines.push('Возвраты розыгрышей не загружены — итог возвратов неполный.');
    return lines.join('\n');
  }
