    var form=editor.querySelector('[data-form="create"]'),known=(data.playerDirectory||[]).find(function(p){return p.room===parsed.room&&p.playerId===String(parsed.playerId||'');});if(known){var picker=form.querySelector('[data-player-picker]');picker.dataset.profileKey=known.profileKey;picker.querySelector('[data-player-query]').value=known.nick||known.name||known.playerId;picker.querySelector('[data-player-caption]').textContent='Выбрано: '+known.room+' · ID '+known.playerId;picker.querySelector('[data-player-choices]').innerHTML=accountChoicesHtml(known.profileKey);}
