    setBusy(true);try{data=await api(operation);var saved=(data.playerDirectory||[]).find(function(p){return p.room===operation.room&&p.playerId===operation.playerId;});if(saved){picker.dataset.profileKey=saved.profileKey;if(side==='to')picker.dataset.playerId=saved.playerId;}var confirmationBox=picker.querySelector('[data-account-link-confirm]');if(confirmationBox)confirmationBox.remove();if(scope.dataset.form==='transfer')syncTransferAccounts(scope);picker.querySelector('[data-player-caption]').textContent='Сохранено: '+operation.room+' · ID '+operation.playerId;tell('Аккаунт игрока сохранён. Теперь доступен в поиске.');}catch(error){handleError(error);}finally{setBusy(false);}
